import pandas as pd
import numpy as np

# Load the data
no2_data = pd.read_csv('chunks_csv/getisord/getisord_no2_Q1_2023.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Identify missing values and exclude them
no2_data = no2_data.dropna(subset=['avg_no2_value'])

# Create a new column that represents the sum of NO2 values for each borough and its neighbors
neighborhoods = {}
for index, row in adjacency_data.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in neighborhoods:
        neighborhoods[borough] = []
    if neighbor not in neighborhoods:
        neighborhoods[neighbor] = []
    neighborhoods[borough].append(neighbor)
    neighborhoods[neighbor].append(borough)

neighborhoods = {k: v for k, v in neighborhoods.items() if k in no2_data['borough'].values}

# Calculate the sum of NO2 values for each neighborhood
neighborhood_no2 = {}
for borough, neighbors in neighborhoods.items():
    neighborhood_no2[borough] = no2_data.loc[no2_data['borough'].isin(neighbors | [borough]), 'avg_no2_value'].sum()

# Calculate the mean and standard deviation of the NO2 values for all neighborhoods
mean_no2 = np.mean(list(neighborhood_no2.values()))
std_no2 = np.std(list(neighborhood_no2.values()))

# Calculate the z-score for each neighborhood
z_scores = {}
for borough, no2_value in neighborhood_no2.items():
    if np.isnan(no2_value):
        z_scores[borough] = np.nan
    else:
        z_scores[borough] = (no2_value - mean_no2) / std_no2

# Identify hot and cold spots
hot_spots = {borough: z_score for borough, z_score in z_scores.items() if np.abs(z_score) > 1.96}
cold_spots = {borough: z_score for borough, z_score in z_scores.items() if np.abs(z_score) > 1.96 and borough not in hot_spots}

# Print the number of data points used in the analysis
print(f"data_points_used = {len(neighborhood_no2)}")

# Print the list of hot and cold spots
results = []
for borough, z_score in hot_spots.items():
    results.append(f"{borough} (HOT, Gi*={z_score})")
for borough, z_score in cold_spots.items():
    results.append(f"{borough} (COLD, Gi*={z_score})")

print(f"FINAL ANSWER: {', '.join(results)}")
